INSERT INTO artists(id,name,years,place,style,education,photo,bio,fact) VALUES
(1,'Елена Воробьёва','род. 1974','Санкт-Петербург, Россия','Пейзаж, импрессионизм','Институт живописи им. И. Е. Репина','assets/img/a-elena.jpg','Елена Воробьёва пишет пейзажи уже больше двадцати лет. Её манеру легко узнать по спокойному свету.','Персональные выставки в Санкт-Петербурге (2019, 2023).'),
(2,'Иван Соколов','1948–2019','Москва, Россия','Академический портрет','МГАХИ им. В. И. Сурикова','assets/img/a-ivan.jpg','Иван Соколов — портретист старой школы. Писал медленно, по много сеансов.','К каждой картине — заключение из архива наследников.'),
(3,'Мария Лебедева','род. 1989','Казань, Россия','Натюрморт, современная живопись','Казанское художественное училище','assets/img/a-maria.jpg','Мария Лебедева пишет натюрморты и городские сцены плотным, скульптурным мазком.','Участница выставок в Казани, Москве и Чехии.') ON DUPLICATE KEY UPDATE id=id;
