-- Artos (artos.by) — импорт в phpMyAdmin: создать базу (utf8mb4), открыть вкладку SQL/Импорт и загрузить этот файл.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, pass_hash VARCHAR(255) NOT NULL, role ENUM('user','admin') NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS artists (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, years VARCHAR(80), place VARCHAR(160), style VARCHAR(190), education VARCHAR(255), photo VARCHAR(255), bio TEXT, fact TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS paintings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, artist_id INT UNSIGNED NULL, title VARCHAR(190) NOT NULL, style VARCHAR(120), genre VARCHAR(120), year SMALLINT NULL, technique VARCHAR(160), material VARCHAR(160), size VARCHAR(60), frame VARCHAR(190), price INT NOT NULL DEFAULT 0, status ENUM('available','reserved','sold') NOT NULL DEFAULT 'available', room VARCHAR(190), certificate VARCHAR(255), photo VARCHAR(255), description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_painting_artist FOREIGN KEY (artist_id) REFERENCES artists(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, painting_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(60) NOT NULL, email VARCHAR(190), address VARCHAR(255), comment TEXT, status ENUM('new','confirmed','paid','shipped','cancelled') NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_order_painting FOREIGN KEY (painting_id) REFERENCES paintings(id) ON DELETE SET NULL, CONSTRAINT fk_order_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

